// T1 - Parse et classifier les URLs du sitemap
const html = $input.item.json.data;
const urlPattern = /href="(https:\/\/schoolswp\.com\/[^"]+)"/g;
const urls = [];
let match;
while ((match = urlPattern.exec(html)) !== null) {
  const url = match[1];
  // Classification basique par pattern d'URL
  let type_page = 'article';
  let cluster = 'Divers';
  let role_SEO = 'support';

  if (url.match(/\/seo|rank-math|yoast/)) { cluster = 'SEO'; }
  if (url.match(/\/lms|learndash|tutor|learnpress/)) { cluster = 'LMS'; }
  if (url.match(/\/plugin|extension|outil/)) { cluster = 'Plugins'; }
  if (url.match(/\/hebergement|hosting/)) { cluster = 'Hebergement'; }
  if (url.match(/\/automatisation|n8n|workflow/)) { cluster = 'Automatisation'; }
  if (url.split('/').filter(Boolean).length <= 2) { type_page = 'hub'; role_SEO = 'pilier'; }

  urls.push({
    url,
    type_page,
    langue: url.includes('/en/') ? 'en' : url.includes('/de/') ? 'de' : 'fr',
    cluster,
    sous_cluster: '',
    role_SEO,
    role_business: 'lead',
    priorite: role_SEO === 'pilier' ? 'P1' : 'P2',
    observations: 'Classifié automatiquement — À VALIDER',
    notes: ''
  });
}
return urls.map(u => ({json: u}));

// T4 - Parser les résultats DataForSEO
const data = $input.item.json;
const results = [];

if (data.tasks && data.tasks[0] && data.tasks[0].result) {
  const keyword = data.tasks[0].data.keyword;
  const items = data.tasks[0].result[0].items || [];
  const top3 = items.slice(0, 3).map(i => i.domain);
  const schoolsWP_present = items.slice(0, 10).some(i => i.domain.includes('schoolswp'));

  results.push({
    mot_cle: keyword,
    top_domains: top3.join(', '),
    top_format: 'À classifier manuellement',
    schoolsWP_present,
    gap: schoolsWP_present ? '' : 'Absent du Top 10 — À VALIDER',
    priorite: 'P2'
  });
}

return results.map(r => ({json: r}));

// T10 - Consolider le backlog depuis tous les onglets
// Ce node agrège les actions de T2 à T9
const actions = $input.all();
let id = 1;

return actions.map(item => ({
  json: {
    id: `SEO-${String(id++).padStart(3, '0')}`,
    action: item.json.action || item.json.issue || 'À définir',
    categorie: item.json.categorie || 'indexation',
    impact_SEO: item.json.impact || item.json.impact_SEO || 'M',
    impact_business: item.json.impact_business || 'M',
    effort: item.json.effort || 'M',
    priorite: item.json.priority || item.json.priorite || 'P2',
    horizon: (item.json.priority === 'P1' || item.json.priorite === 'P1') ? '30j' : '60j',
    outils: 'WordPress, Rank Math',
    owner: 'Michael KIHL',
    etat: 'todo'
  }
}));
